def book(path,pages,cover=True):
 c=canvas.Canvas(str(path),pagesize=(540,720));c.setTitle('AI Growing Field Guide' if cover else 'Equipment Quickstart')
 for n,(title,subtitle,sections) in enumerate(pages,1):
  c.setFillColor(HexColor('#f6f4ec'));c.rect(0,0,540,720,fill=1,stroke=0)
  c.setFillColor(HexColor('#153c2a'));c.rect(0,680,540,40,fill=1,stroke=0)
  c.setFillColor(HexColor('#c6f28e'));c.setFont('Helvetica-Bold',9);c.drawString(32,695,'MASTERGROWBOT / FIELD NOTES')
  c.bookmarkPage(f'p{n}');c.addOutlineEntry(title,f'p{n}',0)
  y=650
  def para(text,size=11,bold=False,color='#20372b',gap=12):
   nonlocal y
   p=Paragraph(escape(text).replace('\n','<br/>'),ParagraphStyle('p',fontName='Helvetica-Bold' if bold else 'Helvetica',fontSize=size,leading=size*1.45,textColor=HexColor(color),splitLongWords=True))
   _,h=p.wrap(476,650)
   if y-h<48:raise ValueError(f'Overflow {path} page {n}: {text[:30]}')
   p.drawOn(c,32,y-h);y-=h+gap
  para(title,25,True,gap=9);para(subtitle,12,color='#5b6d60',gap=20)
  if n==1 and cover:
   c.drawImage(str(R/'public/images/premium-2026/guide-editorial.webp'),32,y-180,476,180,preserveAspectRatio=True,anchor='c');y-=195
  for heading,body in sections:
   para(heading.upper(),9,True,color='#346b47',gap=5);para(body,11,gap=15)
  c.setStrokeColor(HexColor('#cfdbcf'));c.line(32,38,508,38)
  c.setFillColor(HexColor('#53665a'));c.setFont('Helvetica',8);c.drawString(32,23,'NOVEMBER 2026 / Observations first. AI suggestions reviewed.');c.drawRightString(508,23,str(n));c.showPage()
 c.save()

book(OUT/'ai-growing-field-guide-review.pdf',PAGES)
quick=[('Equipment Quickstart','A useful record in 15 minutes',PAGES[2][2]),PAGES[4],PAGES[6],PAGES[19]]
book(PUBLIC/'equipment-quickstart-free.pdf',quick,False)
